import{_ as o,o as r,c as e,a5 as a}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"实际项目代码","description":"","frontmatter":{"title":"实际项目代码","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","常见需求","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第十部分：常见需求/实际项目代码.md","filePath":"posts/java快速入门/第十部分：常见需求/实际项目代码.md"}'),n={name:"posts/java快速入门/第十部分：常见需求/实际项目代码.md"};function i(s,t,l,p,u,g){return r(),e("div",null,[...t[0]||(t[0]=[a('<div><p>在这段代码中，后端的Spring Boot项目使用了一个跨域配置类（CorsAllConfig），它允许特定的前端来源进行跨域请求。下面我会对每行代码进行解释，并给出解决跨域问题的方法。</p><p>代码注释如下： package com.dhcc.common.config; // 定义了这个类的包位置</p><p>import org.springframework.context.annotation.Configuration; // 导入Configuration注解，表明这是一个配置类 import org.springframework.web.servlet.config.annotation.CorsRegistry; // 导入跨域配置注册类 import org.springframework.web.servlet.config.annotation.WebMvcConfigurer; // 导入WebMvcConfigurer接口，该接口中定义了一些回调方法，用于自定义Spring MVC的配置</p><p>@Configuration // 声明这个类是一个配置类 public class CorsAllConfig implements WebMvcConfigurer { // 这个类实现了WebMvcConfigurer接口，用来自定义Spring MVC的配置</p><p>@Override // 重写了WebMvcConfigurer接口的addCorsMappings方法 public void addCorsMappings(CorsRegistry registry) { // 使用跨域配置注册类来添加跨域配置 registry.addMapping(&quot;/CDbadbehaviour&quot;) // 指定需要跨域的路径，这里的&quot;/CDbadbehaviour&quot;应该改为你需要的路径，或者使用&quot;/**&quot;来表示所有路径都允许跨域 // .allowedOrigins(&quot;<a href="https://www.cwhida.org.cn" target="_blank" rel="noreferrer">https://www.cwhida.org.cn</a>&quot;) // 允许这个源进行跨域请求，注释了，所以目前不生效 // .allowedOrigins(&quot;<a href="https://scjg.mwr.cn" target="_blank" rel="noreferrer">https://scjg.mwr.cn</a>&quot;) // 允许这个源进行跨域请求，注释了，所以目前不生效 .allowedOrigins(&quot;<a href="http://192.168.1.108:5173" target="_blank" rel="noreferrer">http://192.168.1.108:5173</a>&quot;) // 允许这个源进行跨域请求 .allowedMethods(&quot;GET&quot;, &quot;POST&quot;, &quot;PUT&quot;, &quot;OPTIONS&quot;, &quot;DELETE&quot;, &quot;PATCH&quot;) // 允许这些HTTP方法进行跨域请求 .allowedHeaders(&quot;*&quot;) // 允许所有的HTTP头信息进行跨域请求 .allowCredentials(true); // 允许请求带有凭证信息，如cookies等 }</p><p>} 你的问题是前端访问<a href="http://192.168.1.108:18088/hzz/inspectionTask/getTaskRecordCount%E8%BF%99%E4%B8%AA%E6%8E%A5%E5%8F%A3%E6%97%B6%E5%8F%91%E7%94%9F%E4%BA%86%E8%B7%A8%E5%9F%9F%E9%97%AE%E9%A2%98%E3%80%82%E5%8F%AF%E4%BB%A5%E5%B0%86%E8%BF%99%E4%B8%AA%E9%85%8D%E7%BD%AE%E7%B1%BB%E8%BF%9B%E8%A1%8C%E4%BF%AE%E6%94%B9%EF%BC%8C%E5%85%81%E8%AE%B8%E5%89%8D%E7%AB%AF%E7%9A%84%E6%9D%A5%E6%BA%90%E8%BF%9B%E8%A1%8C%E8%B7%A8%E5%9F%9F%E8%AF%B7%E6%B1%82%E3%80%82" target="_blank" rel="noreferrer">http://192.168.1.108:18088/hzz/inspectionTask/getTaskRecordCount这个接口时发生了跨域问题。可以将这个配置类进行修改，允许前端的来源进行跨域请求。</a></p><p>例如，假设你的前端运行在<a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>，那么可以修改allowedOrigins方法的参数为<a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>。同时，你需要将addMapping方法的参数修改为/hzz/inspectionTask/getTaskRecordCount或者/**以允许跨域请求。</p><p>修改后的代码如下： @Configuration public class CorsAllConfig implements WebMvcConfigurer {</p><p>@Override public void addCorsMappings(CorsRegistry registry) { registry.addMapping(&quot;/**&quot;) .allowedOrigins(&quot;<a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>&quot;) .allowedMethods(&quot;GET&quot;, &quot;POST&quot;, &quot;PUT&quot;, &quot;OPTIONS&quot;, &quot;DELETE&quot;, &quot;PATCH&quot;) .allowedHeaders(&quot;*&quot;) .allowCredentials(true); }</p><p>} 注意，这个只是一个例子，你需要将allowedOrigins方法的参数改为你的前端实际运行的地址。</p></div>',1)])])}const E=o(n,[["render",i]]);export{d as __pageData,E as default};
